package dev.mateuszsury.androidagent;

import android.database.*;
import android.os.*;
import android.provider.DocumentsContract;
import android.provider.DocumentsProvider;
import java.io.*;

/** Synthetic SAF provider in the test APK only. Never shipped in androidagent. */
public class UsbFixtureProvider extends DocumentsProvider {
    static final String AUTH="dev.mateuszsury.androidagent.tests.documents";
    static boolean offline;
    static volatile java.util.concurrent.CountDownLatch queryGate;
    static volatile boolean queryWaiting;
    private File file(String id)throws FileNotFoundException{if(!id.matches("(?:rw|ro|unknown|offline)(?:/[A-Za-z0-9._-]+)?"))throw new FileNotFoundException(id);File f=new File(getContext().getFilesDir(),"usb-fixture/"+id);f.getParentFile().mkdirs();return f;}
    @Override public boolean onCreate(){return true;}
    @Override public Cursor queryRoots(String[] projection){MatrixCursor c=new MatrixCursor(new String[]{DocumentsContract.Root.COLUMN_ROOT_ID,DocumentsContract.Root.COLUMN_DOCUMENT_ID,DocumentsContract.Root.COLUMN_TITLE,DocumentsContract.Root.COLUMN_FLAGS});for(String id:new String[]{"rw","ro","unknown","offline"})c.addRow(new Object[]{id,id,"Fixture "+id,DocumentsContract.Root.FLAG_SUPPORTS_CREATE|DocumentsContract.Root.FLAG_SUPPORTS_IS_CHILD});return c;}
    private void row(MatrixCursor c,String id)throws FileNotFoundException{File f=file(id);boolean directory=!id.contains("/");if(directory)f.mkdirs();boolean ro=id.startsWith("ro");String[] columns=c.getColumnNames();Object[] values=new Object[columns.length];for(int i=0;i<columns.length;i++){String col=columns[i];if(col.equals(DocumentsContract.Document.COLUMN_DOCUMENT_ID))values[i]=id;else if(col.equals(DocumentsContract.Document.COLUMN_DISPLAY_NAME))values[i]=directory?id:f.getName();else if(col.equals(DocumentsContract.Document.COLUMN_MIME_TYPE))values[i]=directory?DocumentsContract.Document.MIME_TYPE_DIR:"application/octet-stream";else if(col.equals(DocumentsContract.Document.COLUMN_SIZE))values[i]=id.startsWith("unknown")?null:f.length();else if(col.equals(DocumentsContract.Document.COLUMN_FLAGS))values[i]=ro?0:DocumentsContract.Document.FLAG_SUPPORTS_WRITE|DocumentsContract.Document.FLAG_SUPPORTS_DELETE|DocumentsContract.Document.FLAG_DIR_SUPPORTS_CREATE;}c.addRow(values);}
    private MatrixCursor cursor(String[] projection){return new MatrixCursor(projection!=null?projection:new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_FLAGS});}
    @Override public Cursor queryDocument(String id,String[] projection)throws FileNotFoundException{if(id.startsWith("offline")&&offline)throw new FileNotFoundException("media_unavailable fixture");MatrixCursor c=cursor(projection);row(c,id);return c;}
    @Override public Cursor queryChildDocuments(String id,String[] projection,String sort)throws FileNotFoundException{java.util.concurrent.CountDownLatch gate=queryGate;if(gate!=null){queryWaiting=true;try{gate.await(8,java.util.concurrent.TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}}MatrixCursor c=cursor(projection);File[] files=file(id).listFiles();if(files!=null){java.util.Arrays.sort(files,java.util.Comparator.comparing(File::getName));for(File f:files)row(c,id+"/"+f.getName());}return c;}
    @Override public boolean isChildDocument(String parent,String child){return child.startsWith(parent+"/");}
    @Override public ParcelFileDescriptor openDocument(String id,String mode,CancellationSignal signal)throws FileNotFoundException{if(id.startsWith("ro")&&!mode.equals("r"))throw new FileNotFoundException("readonly fixture");if(id.startsWith("offline")&&offline)throw new FileNotFoundException("media_unavailable fixture");if(!mode.equals("r")&&id.endsWith("-partial.bin")){try{ParcelFileDescriptor[] pipe=ParcelFileDescriptor.createReliablePipe();File target=file(id);new Thread(()->{try{byte[] b=new byte[4];InputStream input=new FileInputStream(pipe[0].getFileDescriptor());int n=input.read(b);try(OutputStream out=new FileOutputStream(target)){out.write(b,0,n);}pipe[0].closeWithError("fixture media unplugged after partial write");}catch(Exception ignored){}},"partial-provider-fixture").start();return pipe[1];}catch(IOException e){throw new FileNotFoundException(e.toString());}}return ParcelFileDescriptor.open(file(id),ParcelFileDescriptor.parseMode(mode));}
    @Override public String createDocument(String parent,String mime,String name)throws FileNotFoundException{if(parent.startsWith("ro"))throw new FileNotFoundException("readonly");String id=parent+"/"+name;try{if(!file(id).createNewFile())throw new IOException("exists");return id;}catch(IOException e){throw new FileNotFoundException(e.toString());}}
    @Override public void deleteDocument(String id)throws FileNotFoundException{if(id.startsWith("ro")||!file(id).delete())throw new FileNotFoundException("delete refused");}
    @Override public Bundle call(String method,String arg,Bundle extras){if(method.equals("fixture_offline")){offline=Boolean.parseBoolean(arg);return new Bundle();}if(method.equals("fixture_query_gate")){if("hold".equals(arg)){queryWaiting=false;queryGate=new java.util.concurrent.CountDownLatch(1);}else if("release".equals(arg)){java.util.concurrent.CountDownLatch gate=queryGate;queryGate=null;if(gate!=null)gate.countDown();}Bundle b=new Bundle();b.putBoolean("waiting",queryWaiting);return b;}if(method.equals("fixture_many_files")){try{for(int i=0;i<205;i++){File f=file("rw/page-fixture-"+String.format(java.util.Locale.US,"%03d",i)+".bin");if("create".equals(arg))f.createNewFile();else f.delete();}return new Bundle();}catch(IOException e){throw new IllegalStateException(e);}}return super.call(method,arg,extras);}
}
